style.css:
@-moz-document domain("google.com") {
/* Body background and font */
  body {
    background-color: #000 !important; /* black background */
    font-family: Arial, sans-serif;
    color: #00cfff !important; /* sky blue */
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    height: 100vh;
  }

  /* Hide all unnecessary elements */
  #hplogo, .gb_ce, #fbar, #prm, #pmocntr2, input[name="btnK"], input[name="btnI"] {
    display: none !important;
  }

  /* Replace logo with text */
  #logo {
    display: block !important;
    width: auto !important;
    height: auto !important;
    content: "Google";
    font-size: 60px !important;
    color: #00cfff !important;
    font-weight: bold !important;
    text-align: center !important;
    margin-bottom: 40px !important;
    background: none !important;
  }

  /* Center the search box */
  form {
    display: flex !important;
    justify-content: center !important;
    width: 100% !important;
  }

  /* Search input styling */
  input[name="q"] {
    background-color: #111 !important; /* dark input */
    color: #00cfff !important; /* sky blue text */
    border: 2px solid #00cfff !important;
    border-radius: 5px !important;
    padding: 12px 20px !important;
    font-size: 18px !important;
    width: 400px !important;
    outline: none !important;
  }

  /* Hide placeholder text color */
  input[name="q"]::placeholder {
    color: #00cfff !important;
  }
}
